list_tax_profiles.code:
final response =
    await client.taxProfiles.listTaxProfiles(queryParams: {'limit': 20});
final taxProfiles = (response.map as Map)['tax_profiles'] as List;
for (final taxProfile in taxProfiles) {
  print('${(taxProfile as Map)['id']} ${taxProfile['name']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

create_tax_profile.code:
final response = await client.taxProfiles.createTaxProfile({
  'tax_profile': {
    'name': 'Wholesale',
    'description': 'Profile for wholesale customers',
  },
});
final taxProfile = (response.map as Map)['tax_profile'] as Map;
print(taxProfile['id']);

get_tax_profile.code:
final response = await client.taxProfiles.getTaxProfile(2);
final taxProfile = (response.map as Map)['tax_profile'] as Map;
print('${taxProfile['name']} ${taxProfile['default']}');

